// ParEval 03: axpy — z = alpha * x + y elementwise (BLAS-1).
//
// Each output element is computed independently and once, so any
// correct parallel implementation produces byte-identical results.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][double alpha][double x[N]][double y[N]]
//   argv[2] = output.bin  [double z[N]]   z[i] = alpha * x[i] + y[i]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    double alpha = 0.0;
    if (std::fread(&N,     sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&alpha, sizeof(double),  1, fin) != 1)            { std::fclose(fin); return 1; }
    std::vector<double> x(N), y(N);
    if (std::fread(x.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    if (std::fread(y.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    std::vector<double> z(N);
    for (int i = 0; i < N; ++i) z[i] = alpha * x[i] + y[i];

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(z.data(), sizeof(double), N, fout);
    std::fclose(fout);
    return 0;
}

