// 18_graph_count_components — serial reference
//
// Count the number of connected components in the undirected graph
// defined by an N x N row-major adjacency matrix A.
//
// Binary I/O contract
// -------------------
//   argv[1] = path to input.bin
//     [int32 N]              graph size
//     [int32 A[N*N]]         adjacency matrix, row-major,
//                            A[i*N+j] in {0,1}, symmetric, A[i*N+i]=0
//   argv[2] = path to output.bin
//     [int32 result]         number of connected components
//
// Build:
//   g++ -O3 -std=c++17 main.cpp -o main
//
// Usage:
//   ./main input.bin output.bin

#include <chrono>
#include <cstdint>
#include <cstdio>
#include <vector>

static int componentCount(const std::vector<int>& A, int N) {
    // Iterative DFS to avoid stack overflow on large dense graphs.
    std::vector<bool> visited(N, false);
    std::vector<int> stack;
    int count = 0;
    for (int s = 0; s < N; ++s) {
        if (visited[s]) continue;
        stack.push_back(s);
        visited[s] = true;
        while (!stack.empty()) {
            int node = stack.back();
            stack.pop_back();
            const int* row = A.data() + (std::size_t)node * N;
            for (int i = 0; i < N; ++i) {
                if (row[i] == 1 && !visited[i]) {
                    visited[i] = true;
                    stack.push_back(i);
                }
            }
        }
        ++count;
    }
    return count;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: %s <input.bin> <output.bin>\n", argv[0]);
        return 1;
    }

    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) {
        std::fprintf(stderr, "ERROR: cannot open input %s\n", argv[1]);
        return 1;
    }
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) {
        std::fprintf(stderr, "ERROR: invalid or missing N\n");
        std::fclose(fin);
        return 1;
    }

    std::vector<int> A((std::size_t)N * (std::size_t)N);
    static_assert(sizeof(int) == sizeof(int32_t), "int must be 32-bit");
    std::size_t want = (std::size_t)N * (std::size_t)N;
    if (std::fread(A.data(), sizeof(int32_t), want, fin) != want) {
        std::fprintf(stderr, "ERROR: failed reading A (%zu int32_t)\n", want);
        std::fclose(fin);
        return 1;
    }
    std::fclose(fin);

    auto t0 = std::chrono::steady_clock::now();
    int result = componentCount(A, N);
    auto t1 = std::chrono::steady_clock::now();
    double compute_ms =
        std::chrono::duration<double, std::milli>(t1 - t0).count();
    std::fprintf(stderr, "[serial] compute_only_ms=%.3f\n", compute_ms);

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) {
        std::fprintf(stderr, "ERROR: cannot open output %s\n", argv[2]);
        return 1;
    }
    int32_t result32 = result;
    if (std::fwrite(&result32, sizeof(int32_t), 1, fout) != 1) {
        std::fprintf(stderr, "ERROR: failed writing result\n");
        std::fclose(fout);
        return 1;
    }
    std::fclose(fout);

    return 0;
}

// ParEval 21: histogram — bin values in [0, 100] into 10 bins of width 10.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][double x[N]]   each x[i] in [0, 100]
//   argv[2] = output.bin  [int64 bins[10]]
//
// Bin assignment matches the prompt:
//   bins[k] = count of x[i] in [10*k, 10*(k+1))
// for k = 0..9. The boundary value 100.0 is conventionally clamped into
// bin 9 (otherwise it would fall outside any half-open bin).

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    std::vector<double> x(N);
    if (std::fread(x.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    int64_t bins[10] = {0};
    for (int i = 0; i < N; ++i) {
        int b = (int)(x[i] / 10.0);
        if (b < 0)  b = 0;
        if (b > 9)  b = 9;
        bins[b]++;
    }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(bins, sizeof(int64_t), 10, fout);
    std::fclose(fout);
    return 0;
}

// ParEval 25: reduceLogicalXOR — XOR over all booleans in x.
// Output is single bool (encoded as int8: 0 or 1).
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int8 x[N]]    each x[i] in {0, 1}
//   argv[2] = output.bin  [int8 result]            XOR of all x[i]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    std::vector<int8_t> x(N);
    if (std::fread(x.data(), sizeof(int8_t), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    int8_t r = 0;
    for (int i = 0; i < N; ++i) r ^= (x[i] & 1);

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(&r, sizeof(int8_t), 1, fout);
    std::fclose(fout);
    return 0;
}

// ParEval 30: prefix-sum (inclusive scan) over a double array.
//
// output[i] = sum(x[0..i])   for i in [0, N)
//
// Different parallel scan algorithms (Hillis-Steele, Blelloch tree,
// SIMD lanes) accumulate in different orders, producing slightly
// different bytes due to float non-associativity. The checker accepts
// any element-wise tolerance match.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][double x[N]]
//   argv[2] = output.bin  [double output[N]]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    std::vector<double> x(N);
    if (std::fread(x.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    std::vector<double> y(N);
    double acc = 0.0;
    for (int i = 0; i < N; ++i) { acc += x[i]; y[i] = acc; }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(y.data(), sizeof(double), N, fout);
    std::fclose(fout);
    return 0;
}

