"""Element-wise tolerance check for prefix-sum output (P010).

Recompute the inclusive scan in float64 and compare against candidate
with a relative + absolute tolerance scaled to the running magnitude.
"""
import struct


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 4:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    if N <= 0:
        return {"valid": False, "reason": f"invalid N={N}"}
    expected_in = 4 + 8 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    x = struct.unpack(f"<{N}d", input_bytes[4:expected_in])

    if len(output_bytes) != 8 * N:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected {8*N}"}
    got = struct.unpack(f"<{N}d", output_bytes)

    rtol, atol = 1e-9, 1e-6
    acc = 0.0
    max_diff = 0.0
    bad_idx = -1
    for i in range(N):
        acc += x[i]
        diff = abs(got[i] - acc)
        tol  = max(atol, rtol * max(abs(acc), 1.0))
        if diff > tol and bad_idx < 0:
            bad_idx = i
        if diff > max_diff:
            max_diff = diff
    if bad_idx >= 0:
        return {"valid": False,
                "reason": (f"output[{bad_idx}] diff = {max_diff:.3e} exceeds "
                           f"tolerance (atol={atol:.1e}, rtol={rtol:.1e})")}
    return {"valid": True,
            "reason": f"all {N} elements within tolerance (max diff = {max_diff:.3e})"}

