// ParEval 36: contains — return true iff target is in x.
// Output is a single bool (encoded as int8: 0 or 1).
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 target][int32 x[N]]
//   argv[2] = output.bin  [int8 result]   1 if target found, 0 otherwise

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0, target = 0;
    if (std::fread(&N,      sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&target, sizeof(int32_t), 1, fin) != 1)            { std::fclose(fin); return 1; }
    std::vector<int32_t> x(N);
    if (std::fread(x.data(), sizeof(int32_t), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    int8_t r = 0;
    for (int i = 0; i < N; ++i) if (x[i] == target) { r = 1; break; }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(&r, sizeof(int8_t), 1, fout);
    std::fclose(fout);
    return 0;
}

// ParEval 41: kth-smallest — return the value that would be at index k
// of the sorted array (0-indexed; k in [0, N)).
//
// The output VALUE is uniquely determined regardless of how ties at
// rank k are broken — bytes match for any correct implementation.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 k][int32 x[N]]
//   argv[2] = output.bin  [int32 result]    result = sort(x)[k]

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0, k = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&k, sizeof(int32_t), 1, fin) != 1 || k < 0 || k >= N) {
        std::fclose(fin); return 1;
    }
    std::vector<int32_t> x(N);
    if (std::fread(x.data(), sizeof(int32_t), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    std::nth_element(x.begin(), x.begin() + k, x.end());
    int32_t r = x[k];

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(&r, sizeof(int32_t), 1, fout);
    std::fclose(fout);
    return 0;
}

// ParEval 55: relu — apply max(0, x) elementwise to a double array.
// Output is fully deterministic; bytes match for any correct impl.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][double x[N]]
//   argv[2] = output.bin  [double y[N]]   y[i] = (x[i] > 0) ? x[i] : 0

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) { std::fprintf(stderr,"Usage: %s in out\n", argv[0]); return 1; }
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    std::vector<double> x(N);
    if (std::fread(x.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    for (int i = 0; i < N; ++i) if (x[i] < 0) x[i] = 0.0;

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(x.data(), sizeof(double), N, fout);
    std::fclose(fout);
    return 0;
}

// Apply x[i] = x[i] * x[i] to every element. Output array same shape as input.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 x[N]]
//   argv[2] = output.bin  [int32 y[N]]   where y[i] = x[i] * x[i]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: %s <input.bin> <output.bin>\n", argv[0]);
        return 1;
    }
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) { std::fprintf(stderr, "open input failed\n"); return 1; }
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) {
        std::fprintf(stderr, "bad N\n"); std::fclose(fin); return 1;
    }
    std::vector<int32_t> x(N);
    if (std::fread(x.data(), sizeof(int32_t), N, fin) != (std::size_t)N) {
        std::fprintf(stderr, "short read\n"); std::fclose(fin); return 1;
    }
    std::fclose(fin);

    std::vector<int32_t> y(N);
    for (int i = 0; i < N; ++i) y[i] = x[i] * x[i];

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) { std::fprintf(stderr, "open output failed\n"); return 1; }
    std::fwrite(y.data(), sizeof(int32_t), N, fout);
    std::fclose(fout);
    return 0;
}

// Reduce-sum of a float32 array.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][float32 x[N]]
//   argv[2] = output.bin  [float32 sum]
//
// NOTE: this is a non-unique-bytes problem. Different reduction orders
// (sequential left-to-right vs. tree-reduce vs. SIMD) produce slightly
// different float32 results due to non-associativity. Our checker
// accepts answers within a relative tolerance.

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: %s <input.bin> <output.bin>\n", argv[0]);
        return 1;
    }
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) { std::fprintf(stderr, "open input failed\n"); return 1; }
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) {
        std::fprintf(stderr, "bad N\n"); std::fclose(fin); return 1;
    }
    std::vector<float> x(N);
    if (std::fread(x.data(), sizeof(float), N, fin) != (std::size_t)N) {
        std::fprintf(stderr, "short read\n"); std::fclose(fin); return 1;
    }
    std::fclose(fin);

    // Serial left-to-right summation
    float sum = 0.0f;
    for (int i = 0; i < N; ++i) sum += x[i];

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) { std::fprintf(stderr, "open output failed\n"); return 1; }
    std::fwrite(&sum, sizeof(float), 1, fout);
    std::fclose(fout);
    return 0;
}

