"""Checker for reduce_sum_floats (P004).

Recompute the sum in double precision and accept the candidate within
relative + absolute tolerance.
"""
import struct


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 4:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    if N <= 0:
        return {"valid": False, "reason": f"invalid N={N}"}
    expected_in = 4 + 4 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    x = struct.unpack(f"<{N}f", input_bytes[4:expected_in])

    if len(output_bytes) != 4:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected 4"}
    got = struct.unpack("<f", output_bytes)[0]

    # ground-truth sum in float64 (Python doubles)
    expected = sum(float(v) for v in x)

    # tolerance scaled to float32 + accumulated relative error over N adds
    rtol = 1e-4
    atol = max(1e-4 * N, 1e-3)
    diff = abs(got - expected)
    if diff <= max(atol, rtol * max(abs(expected), 1.0)):
        return {"valid": True,
                "reason": (f"|got - expected| = {diff:.3e} within tolerance "
                           f"(atol={atol:.1e}, rtol={rtol:.1e})")}
    return {"valid": False,
            "reason": (f"|got - expected| = {diff:.3e} exceeds tolerance "
                       f"(got={got:.6g}, expected={expected:.6g})")}

