// HeCBench `accuracy` benchmark — count rows where the labelled column's
// score is in the top-K (with HeCBench's specific tie-break rule:
// equal scores at columns <= label count as "ahead").
//
// Adapted from HeCBench/accuracy-cuda's `reference()` function.
//
// Binary I/O contract:
//   argv[1] = input.bin
//     [int32 N][int32 D][int32 top_k]
//     [float32 X[N*D]]            row-major prediction matrix
//     [int32   labels[N]]         each label in [0, D)
//   argv[2] = output.bin
//     [int32 count]               number of rows accurate within top-k

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: %s <input.bin> <output.bin>\n", argv[0]);
        return 1;
    }
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) { std::fprintf(stderr, "open input failed\n"); return 1; }

    int32_t N = 0, D = 0, top_k = 0;
    if (std::fread(&N,     sizeof(int32_t), 1, fin) != 1) goto bad;
    if (std::fread(&D,     sizeof(int32_t), 1, fin) != 1) goto bad;
    if (std::fread(&top_k, sizeof(int32_t), 1, fin) != 1) goto bad;
    if (N <= 0 || D <= 0 || top_k < 0) goto bad;

    {
        std::vector<float> X((std::size_t)N * D);
        if (std::fread(X.data(), sizeof(float), (std::size_t)N * D, fin)
                != (std::size_t)N * D) goto bad;
        std::vector<int32_t> labels(N);
        if (std::fread(labels.data(), sizeof(int32_t), N, fin)
                != (std::size_t)N) goto bad;
        std::fclose(fin);

        int32_t count = 0;
        for (int row = 0; row < N; ++row) {
            int label = labels[row];
            const float label_pred = X[(std::size_t)row * D + label];
            int ngt = 0;
            for (int col = 0; col < D; ++col) {
                float p = X[(std::size_t)row * D + col];
                if (p > label_pred ||
                    (p == label_pred && col <= label)) {
                    ++ngt;
                }
            }
            if (ngt <= top_k) ++count;
        }

        FILE* fout = std::fopen(argv[2], "wb");
        if (!fout) { std::fprintf(stderr, "open output failed\n"); return 1; }
        std::fwrite(&count, sizeof(int32_t), 1, fout);
        std::fclose(fout);
        return 0;
    }

