def check(input_bytes, output_bytes):
    """axpby: z = a*x + b*y. rel_tol=1e-13, abs_tol=1e-14 — covers
    FMA-vs-mul-add and any reasonable cancellation behavior."""
    import struct, math
    if len(input_bytes) < 20:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack_from("<i", input_bytes, 0)[0]
    if N <= 0:
        return {"valid": False, "reason": f"N={N} not positive"}
    expected_in = 4 + 8 + 8 + 8 * 2 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)} != {expected_in}"}
    a = struct.unpack_from("<d", input_bytes, 4)[0]
    b = struct.unpack_from("<d", input_bytes, 12)[0]
    x = struct.unpack_from(f"<{N}d", input_bytes, 20)
    y = struct.unpack_from(f"<{N}d", input_bytes, 20 + 8*N)

    expected_out = 8 * N
    if len(output_bytes) != expected_out:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)} != {expected_out}"}
    z = struct.unpack(f"<{N}d", output_bytes)

    REL = 1e-13
    ABS = 1e-14
    n_bad = 0
    worst_rel = 0.0
    worst_abs = 0.0
    bad_idx = -1
    for i in range(N):
        e = a * x[i] + b * y[i]
        c = z[i]
        if math.isclose(e, c, rel_tol=REL, abs_tol=ABS):
            continue
        n_bad += 1
        bad_idx = i
        ad = abs(e - c)
        if ad > worst_abs: worst_abs = ad
        s = max(abs(e), abs(c), 1e-300)
        rd = ad / s
        if rd > worst_rel: worst_rel = rd
    if n_bad:
        return {"valid": False,
                "reason": f"{n_bad}/{N} elements outside tol (rel<={REL}, abs<={ABS}); "
                          f"worst_rel={worst_rel:.2e}, worst_abs={worst_abs:.2e} @ idx {bad_idx}"}
    return {"valid": True, "reason": "within tolerance"}

