"""Element-wise tolerance check for atan2 output (P013)."""
import math
import struct


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 4:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    if N <= 0:
        return {"valid": False, "reason": f"invalid N={N}"}
    expected_in = 4 + 16 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    y = struct.unpack(f"<{N}d", input_bytes[4:4 + 8*N])
    x = struct.unpack(f"<{N}d", input_bytes[4 + 8*N:expected_in])

    if len(output_bytes) != 8 * N:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected {8*N}"}
    got = struct.unpack(f"<{N}d", output_bytes)

    rtol, atol = 1e-9, 1e-12
    bad_idx, max_diff = -1, 0.0
    for i in range(N):
        ref = math.atan2(y[i], x[i])
        diff = abs(got[i] - ref)
        if diff > max_diff:
            max_diff = diff
        if diff > max(atol, rtol * max(abs(ref), 1.0)) and bad_idx < 0:
            bad_idx = i
    if bad_idx >= 0:
        return {"valid": False,
                "reason": (f"output[{bad_idx}] differs by "
                           f"{max_diff:.3e} (atol={atol:.1e} rtol={rtol:.1e})")}
    return {"valid": True,
            "reason": f"all {N} elements within tolerance (max diff = {max_diff:.3e})"}

