// hecbench_softmax — numerically-stable softmax over a 1D array.
//
// Output: y[i] = exp(x[i] - max(x)) / sum_j(exp(x[j] - max(x)))
//
// Different reduction orders for the sum produce slightly different
// bytes; checker accepts elementwise tolerance.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][double x[N]]
//   argv[2] = output.bin  [double y[N]]

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    std::vector<double> x(N);
    if (std::fread(x.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    double mx = *std::max_element(x.begin(), x.end());
    std::vector<double> y(N);
    double s = 0.0;
    for (int i = 0; i < N; ++i) { y[i] = std::exp(x[i] - mx); s += y[i]; }
    if (s == 0.0) s = 1.0;
    for (int i = 0; i < N; ++i) y[i] /= s;

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(y.data(), sizeof(double), N, fout);
    std::fclose(fout);
    return 0;
}

