"""Element-wise tolerance check for softmax (P015).

Recompute softmax in double, ensure candidate matches within tolerance
and that the sum approximates 1 (canonical normalization).
"""
import math
import struct


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 4:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    if N <= 0:
        return {"valid": False, "reason": f"invalid N={N}"}
    expected_in = 4 + 8 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    x = struct.unpack(f"<{N}d", input_bytes[4:expected_in])

    if len(output_bytes) != 8 * N:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected {8*N}"}
    got = struct.unpack(f"<{N}d", output_bytes)

    # canonical (numerically stable) softmax
    mx = max(x)
    es = [math.exp(v - mx) for v in x]
    s = sum(es)
    expected = [e / s for e in es]

    rtol, atol = 1e-9, 1e-12
    bad_idx, max_diff = -1, 0.0
    for i in range(N):
        diff = abs(got[i] - expected[i])
        if diff > max_diff:
            max_diff = diff
        if diff > max(atol, rtol * max(abs(expected[i]), 1.0)) and bad_idx < 0:
            bad_idx = i
    if bad_idx >= 0:
        return {"valid": False,
                "reason": (f"output[{bad_idx}] differs by {max_diff:.3e} "
                           f"(atol={atol:.1e} rtol={rtol:.1e})")}

    sum_got = sum(got)
    if abs(sum_got - 1.0) > 1e-6:
        return {"valid": False,
                "reason": f"sum(output) = {sum_got:.6e}, expected ≈ 1"}
    return {"valid": True,
            "reason": (f"all {N} elements within tolerance, "
                       f"sum = {sum_got:.6e} (max diff = {max_diff:.3e})")}

