// hecbench_jenkins_hash — Jenkins one-at-a-time 32-bit hash over each
// fixed-length record.
//
// For an input array of bytes with N records of M bytes each, output
// the per-record uint32 hash:
//
//   uint32_t h = 0;
//   for byte b in record:
//     h += b;
//     h += h << 10;
//     h ^= h >> 6;
//   h += h << 3;
//   h ^= h >> 11;
//   h += h << 15;
//
// Output is bit-exact deterministic.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 M][uint8 data[N*M]]
//   argv[2] = output.bin  [uint32 hashes[N]]

#include <cstdint>
#include <cstdio>
#include <vector>

static uint32_t jenkins_oaat(const uint8_t* p, int M) {
    uint32_t h = 0;
    for (int j = 0; j < M; ++j) {
        h += p[j];
        h += h << 10;
        h ^= h >> 6;
    }
    h += h << 3;
    h ^= h >> 11;
    h += h << 15;
    return h;
}

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0, M = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&M, sizeof(int32_t), 1, fin) != 1 || M <= 0) { std::fclose(fin); return 1; }
    std::vector<uint8_t> data((std::size_t)N * (std::size_t)M);
    if (std::fread(data.data(), 1, data.size(), fin) != data.size()) { std::fclose(fin); return 1; }
    std::fclose(fin);

    std::vector<uint32_t> h(N);
    for (int i = 0; i < N; ++i) {
        h[i] = jenkins_oaat(data.data() + (std::size_t)i * M, M);
    }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(h.data(), sizeof(uint32_t), N, fout);
    std::fclose(fout);
    return 0;
}

