// hecbench_layernorm — per-row layer normalization.
//
// For each row r in an N x D matrix X:
//   mean_r = (1/D) * sum_d X[r,d]
//   var_r  = (1/D) * sum_d (X[r,d] - mean_r)^2
//   Y[r,d] = (X[r,d] - mean_r) / sqrt(var_r + eps)
//
// Different reduction orders produce slightly different bytes per row;
// checker accepts elementwise tolerance.
//
// Binary I/O contract:
//   argv[1] = input.bin
//     [int32 N][int32 D][double eps][double X[N*D]]
//   argv[2] = output.bin  [double Y[N*D]]   (row-major)

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0, D = 0;
    double eps = 0.0;
    if (std::fread(&N,   sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&D,   sizeof(int32_t), 1, fin) != 1 || D <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&eps, sizeof(double),  1, fin) != 1) { std::fclose(fin); return 1; }
    std::vector<double> X((std::size_t)N * D), Y((std::size_t)N * D);
    if (std::fread(X.data(), sizeof(double), (std::size_t)N * D, fin)
            != (std::size_t)N * D) { std::fclose(fin); return 1; }
    std::fclose(fin);

    for (int r = 0; r < N; ++r) {
        double m = 0.0;
        for (int d = 0; d < D; ++d) m += X[(std::size_t)r * D + d];
        m /= D;
        double v = 0.0;
        for (int d = 0; d < D; ++d) {
            double t = X[(std::size_t)r * D + d] - m;
            v += t * t;
        }
        v /= D;
        double inv = 1.0 / std::sqrt(v + eps);
        for (int d = 0; d < D; ++d)
            Y[(std::size_t)r * D + d] = (X[(std::size_t)r * D + d] - m) * inv;
    }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(Y.data(), sizeof(double), (std::size_t)N * D, fout);
    std::fclose(fout);
    return 0;
}

