"""Tolerance check for layernorm (P018)."""
import math
import struct


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 16:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    D = struct.unpack("<i", input_bytes[4:8])[0]
    eps = struct.unpack("<d", input_bytes[8:16])[0]
    if N <= 0 or D <= 0:
        return {"valid": False, "reason": f"invalid N={N} or D={D}"}
    expected_in = 16 + 8 * N * D
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    X = struct.unpack(f"<{N*D}d", input_bytes[16:expected_in])

    if len(output_bytes) != 8 * N * D:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected {8*N*D}"}
    Y = struct.unpack(f"<{N*D}d", output_bytes)

    rtol, atol = 1e-9, 1e-9
    bad, max_diff = -1, 0.0
    for r in range(N):
        row_x = X[r*D:(r+1)*D]
        m = sum(row_x) / D
        v = sum((t - m)**2 for t in row_x) / D
        inv = 1.0 / math.sqrt(v + eps)
        for d in range(D):
            ref = (row_x[d] - m) * inv
            diff = abs(Y[r*D + d] - ref)
            if diff > max_diff: max_diff = diff
            if diff > max(atol, rtol * max(abs(ref), 1.0)) and bad < 0:
                bad = r * D + d
    if bad >= 0:
        return {"valid": False,
                "reason": (f"output[{bad}] differs by {max_diff:.3e} "
                           f"(atol={atol:.1e} rtol={rtol:.1e})")}
    return {"valid": True,
            "reason": f"all {N*D} elements within tolerance (max diff = {max_diff:.3e})"}

