    std::vector<double> x(N), g(N);
    if (std::fread(x.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    if (std::fread(g.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    std::vector<double> out(N);
    for (int i = 0; i < N; ++i) out[i] = (x[i] > 0) ? g[i] : 0.0;

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(out.data(), sizeof(double), N, fout);
    std::fclose(fout);
    return 0;
}

// hecbench_grayscale — convert RGB image to grayscale (BT.601 luma).
//
// For each pixel:
//   Y = round(0.299 * R + 0.587 * G + 0.114 * B)
// All channels are uint8; integer arithmetic with fixed weights makes
// the output bit-exact across implementations.
//
// Binary I/O contract:
//   argv[1] = input.bin
//     [int32 H][int32 W][uint8 R[H*W]][uint8 G[H*W]][uint8 B[H*W]]
//   argv[2] = output.bin  [uint8 Y[H*W]]
//
// Implementation note: to keep the result strictly deterministic across
// any sane implementation, we compute in fixed-point (Q15) with a
// fixed rounding rule (round-half-up).

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t H = 0, W = 0;
    if (std::fread(&H, sizeof(int32_t), 1, fin) != 1 || H <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&W, sizeof(int32_t), 1, fin) != 1 || W <= 0) { std::fclose(fin); return 1; }
    std::size_t N = (std::size_t)H * (std::size_t)W;
    std::vector<uint8_t> R(N), G(N), B(N), Y(N);
    if (std::fread(R.data(), 1, N, fin) != N) { std::fclose(fin); return 1; }
    if (std::fread(G.data(), 1, N, fin) != N) { std::fclose(fin); return 1; }
    if (std::fread(B.data(), 1, N, fin) != N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    // Weights as Q15 fixed-point: round(0.299 * 32768) = 9798, etc.
    // 9798 + 19235 + 3735 = 32768 (exactly)
    const uint32_t WR = 9798, WG = 19235, WB = 3735;
    for (std::size_t i = 0; i < N; ++i) {
        uint32_t v = WR * (uint32_t)R[i] + WG * (uint32_t)G[i] + WB * (uint32_t)B[i];
        // round-half-up: add 16384 (= 0.5 * 32768) before shift
        uint32_t y = (v + 16384) >> 15;
        if (y > 255) y = 255;
        Y[i] = (uint8_t)y;
    }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(Y.data(), 1, N, fout);
    std::fclose(fout);
    return 0;
}

// BFS shortest-path tree — serial reference
//
// Compute a BFS tree rooted at vertex 0 in the undirected unweighted graph
// represented by an N×N adjacency matrix. For each vertex v, output
// `parent[v]`:
//   parent[0]  = -1  (source)
//   parent[v]  = -2  (v unreachable from source)
//   parent[v]  = u   (some neighbor u with dist[u] + 1 == dist[v])
//
// The tree is NOT UNIQUE — when v has multiple equidistant predecessors,
// any valid choice is acceptable. The reference here picks the
// lowest-index valid predecessor (forward iteration).
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 A[N*N]]
//   argv[2] = output.bin  [int32 parent[N]]

#include <cstdint>
#include <cstdio>
#include <queue>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: %s <input.bin> <output.bin>\n", argv[0]);
        return 1;
    }
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) { std::fprintf(stderr, "open input failed\n"); return 1; }
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) {
        std::fprintf(stderr, "bad N\n"); std::fclose(fin); return 1;
    }
    std::vector<int> A((std::size_t)N * (std::size_t)N);
    if (std::fread(A.data(), sizeof(int32_t), (std::size_t)N * N, fin)
            != (std::size_t)N * N) {
        std::fprintf(stderr, "short read on A\n"); std::fclose(fin); return 1;
    }
    std::fclose(fin);

    std::vector<int> parent(N, -2);
    parent[0] = -1;
    std::queue<int> q;
    q.push(0);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        const int* row = A.data() + (std::size_t)u * N;
        for (int v = 0; v < N; ++v) {           // forward
            if (row[v] == 1 && parent[v] == -2) {
                parent[v] = u;
                q.push(v);
            }
        }
    }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) { std::fprintf(stderr, "open output failed\n"); return 1; }
    if (std::fwrite(parent.data(), sizeof(int32_t), N, fout) != (std::size_t)N) {
        std::fprintf(stderr, "short write\n"); std::fclose(fout); return 1;
    }
    std::fclose(fout);
    return 0;
}

