import struct
from collections import deque


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    """Return {"valid": bool, "reason": str}.

    Verify the candidate parent[] is a valid BFS shortest-path tree from
    source 0 in the graph described by input.bin.
    """
    if len(input_bytes) < 4:
        return {"valid": False, "reason": "input too short to read N"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    if N <= 0:
        return {"valid": False, "reason": f"invalid N={N}"}
    expected_in = 4 + 4 * N * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    A = struct.unpack(f"<{N*N}i", input_bytes[4:expected_in])

    if len(output_bytes) != 4 * N:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected {4*N}"}
    parent = list(struct.unpack(f"<{N}i", output_bytes))

    # Independent BFS from source 0 to determine true distances
    dist = [-1] * N
    dist[0] = 0
    q = deque([0])
    while q:
        u = q.popleft()
        base = u * N
        for v in range(N):
            if A[base + v] == 1 and dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)

    # source vertex
    if parent[0] != -1:
        return {"valid": False,
                "reason": f"parent[0] = {parent[0]}, expected -1 (source)"}

    # remaining vertices
    for v in range(1, N):
        p = parent[v]
        if dist[v] == -1:
            # v unreachable
            if p != -2:
                return {"valid": False,
                        "reason": f"vertex {v} unreachable from source, "
                                  f"but parent[{v}] = {p}, expected -2"}
            continue
        # v reachable: parent[v] must be a neighbor of v with dist[parent]+1 == dist[v]
        if not (0 <= p < N):
            return {"valid": False,
                    "reason": f"parent[{v}] = {p} out of range [0, {N})"}
        if A[v * N + p] != 1:
            return {"valid": False,
                    "reason": f"parent[{v}] = {p} is not adjacent to {v} "
                              f"(A[{v}][{p}] = {A[v*N+p]})"}
        if dist[p] + 1 != dist[v]:
            return {"valid": False,
                    "reason": f"parent[{v}] = {p}: dist[{p}]+1 = {dist[p]+1} "
                              f"but dist[{v}] = {dist[v]} (not a shortest-path edge)"}

    return {"valid": True, "reason": "valid BFS shortest-path tree"}

