// Sort an array of (key, value) pairs by key in non-decreasing order.
//
// Multiple keys may be equal — the relative order of values among equal
// keys IS NOT FIXED by the spec. Any output that is sorted by key and
// contains the same multiset of pairs as the input is correct.
//
// Reference implementation: stable_sort by key (preserves input order
// for ties).
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 keys[N]][int32 values[N]]
//   argv[2] = output.bin              [int32 keys[N]][int32 values[N]]
//                                      (no leading N — count implicit
//                                       in the file size = 8*N bytes)

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <utility>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: %s <input.bin> <output.bin>\n", argv[0]);
        return 1;
    }
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) { std::fprintf(stderr, "open input failed\n"); return 1; }
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) {
        std::fprintf(stderr, "bad N\n"); std::fclose(fin); return 1;
    }
    std::vector<int32_t> keys(N), values(N);
    if (std::fread(keys.data(),   sizeof(int32_t), N, fin) != (std::size_t)N
     || std::fread(values.data(), sizeof(int32_t), N, fin) != (std::size_t)N) {
        std::fprintf(stderr, "short read\n"); std::fclose(fin); return 1;
    }
    std::fclose(fin);

    std::vector<std::pair<int32_t, int32_t>> pairs(N);
    for (int i = 0; i < N; ++i) pairs[i] = {keys[i], values[i]};
    std::stable_sort(pairs.begin(), pairs.end(),
                     [](auto const& a, auto const& b) {
                         return a.first < b.first;   // sort by key only
                     });
    for (int i = 0; i < N; ++i) {
        keys[i]   = pairs[i].first;
        values[i] = pairs[i].second;
    }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) { std::fprintf(stderr, "open output failed\n"); return 1; }
    std::fwrite(keys.data(),   sizeof(int32_t), N, fout);
    std::fwrite(values.data(), sizeof(int32_t), N, fout);
    std::fclose(fout);
    return 0;
}

