"""Checker for sort_by_key_with_ties (P006).

Validity criteria:
  1. Output keys must be non-decreasing.
  2. The multiset of (key, value) pairs must equal the input's multiset
     (no insertions / deletions / value-shuffling within tie groups
      that doesn't preserve the multiset).
"""
import struct
from collections import Counter


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 4:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    if N <= 0:
        return {"valid": False, "reason": f"invalid N={N}"}
    expected_in = 4 + 8 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    in_keys   = struct.unpack(f"<{N}i", input_bytes[4:4 + 4*N])
    in_values = struct.unpack(f"<{N}i", input_bytes[4 + 4*N:expected_in])

    if len(output_bytes) != 8 * N:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected {8*N}"}
    out_keys   = struct.unpack(f"<{N}i", output_bytes[:4*N])
    out_values = struct.unpack(f"<{N}i", output_bytes[4*N:8*N])

    # 1. non-decreasing by key
    for i in range(1, N):
        if out_keys[i] < out_keys[i-1]:
            return {"valid": False,
                    "reason": f"keys not sorted at index {i}: "
                              f"{out_keys[i-1]} > {out_keys[i]}"}

    # 2. multiset of (key, value) preserved
    if Counter(zip(in_keys, in_values)) != Counter(zip(out_keys, out_values)):
        return {"valid": False,
                "reason": "(key, value) multiset differs from input"}

    return {"valid": True, "reason": "sorted by key, multiset preserved"}

