// lowest-index occurrence (forward scan).
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 values[N]]
//   argv[2] = output.bin  [int32 idx]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: %s <input.bin> <output.bin>\n", argv[0]);
        return 1;
    }
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) { std::fprintf(stderr, "open input failed\n"); return 1; }
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) {
        std::fprintf(stderr, "bad N\n"); std::fclose(fin); return 1;
    }
    std::vector<int32_t> v(N);
    if (std::fread(v.data(), sizeof(int32_t), N, fin) != (std::size_t)N) {
        std::fprintf(stderr, "short read\n"); std::fclose(fin); return 1;
    }
    std::fclose(fin);

    int32_t best_idx = 0;
    int32_t best_val = v[0];
