import struct


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 4:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    if N <= 0:
        return {"valid": False, "reason": f"invalid N={N}"}
    expected_in = 4 + 4 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    v = struct.unpack(f"<{N}i", input_bytes[4:expected_in])

    if len(output_bytes) != 4:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected 4"}
    idx = struct.unpack("<i", output_bytes)[0]

    if not (0 <= idx < N):
        return {"valid": False, "reason": f"idx={idx} out of range [0, {N})"}
    min_val = min(v)
    if v[idx] != min_val:
        return {"valid": False,
                "reason": f"v[{idx}]={v[idx]}, but min(v)={min_val}"}
    return {"valid": True,
            "reason": f"v[{idx}]={v[idx]} matches min"}

