// original_matrix_transpose — transpose an H x W double matrix.
// B[j, i] = A[i, j]   for i in [0,H), j in [0,W)
//
// Per-element copy; byte-deterministic.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 H][int32 W][double A[H*W]]   (row-major)
//   argv[2] = output.bin  [double B[W*H]]                      (row-major,
//                                                                shape W x H)

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t H = 0, W = 0;
    if (std::fread(&H, sizeof(int32_t), 1, fin) != 1 || H <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&W, sizeof(int32_t), 1, fin) != 1 || W <= 0) { std::fclose(fin); return 1; }
    std::size_t N = (std::size_t)H * (std::size_t)W;
    std::vector<double> A(N), B(N);
    if (std::fread(A.data(), sizeof(double), N, fin) != N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    for (int i = 0; i < H; ++i)
        for (int j = 0; j < W; ++j)
            B[(std::size_t)j * H + i] = A[(std::size_t)i * W + j];

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(B.data(), sizeof(double), N, fout);
    std::fclose(fout);
    return 0;
}

// original_2d_jacobi_one_iter — single iteration of the 5-point Jacobi
// stencil on an H x W double grid.
//
//   for interior (i in [1,H-2], j in [1,W-2]):
//     B[i,j] = (A[i-1,j] + A[i+1,j] + A[i,j-1] + A[i,j+1]) * 0.25
//   for boundary (i,j) (Dirichlet): B[i,j] = A[i,j]
//
// Different summation orders for the four neighbors produce slightly
// different bytes per cell — checker accepts elementwise tolerance.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 H][int32 W][double A[H*W]]
//   argv[2] = output.bin  [double B[H*W]]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t H = 0, W = 0;
    if (std::fread(&H, sizeof(int32_t), 1, fin) != 1 || H <= 1) { std::fclose(fin); return 1; }
    if (std::fread(&W, sizeof(int32_t), 1, fin) != 1 || W <= 1) { std::fclose(fin); return 1; }
    std::size_t N = (std::size_t)H * (std::size_t)W;
    std::vector<double> A(N), B(N);
    if (std::fread(A.data(), sizeof(double), N, fin) != N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    // initialize B = A (handles Dirichlet boundary)
    B = A;
    for (int i = 1; i < H - 1; ++i) {
        for (int j = 1; j < W - 1; ++j) {
            std::size_t k = (std::size_t)i * W + j;
            B[k] = (A[k - W] + A[k + W] + A[k - 1] + A[k + 1]) * 0.25;
        }
    }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(B.data(), sizeof(double), N, fout);
    std::fclose(fout);
    return 0;
}

