"""Element-wise tolerance check for 2D Jacobi stencil (P025)."""
import struct


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 8:
        return {"valid": False, "reason": "input too short"}
    H = struct.unpack("<i", input_bytes[:4])[0]
    W = struct.unpack("<i", input_bytes[4:8])[0]
    if H <= 1 or W <= 1:
        return {"valid": False, "reason": f"invalid H={H} or W={W}"}
    N = H * W
    expected_in = 8 + 8 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    A = struct.unpack(f"<{N}d", input_bytes[8:expected_in])

    if len(output_bytes) != 8 * N:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected {8*N}"}
    B = struct.unpack(f"<{N}d", output_bytes)

    rtol, atol = 1e-12, 1e-15
    bad, max_diff = -1, 0.0
    for i in range(H):
        for j in range(W):
            k = i * W + j
            if i == 0 or i == H - 1 or j == 0 or j == W - 1:
                ref = A[k]   # Dirichlet boundary unchanged
            else:
                ref = (A[k - W] + A[k + W] + A[k - 1] + A[k + 1]) * 0.25
            diff = abs(B[k] - ref)
            if diff > max_diff:
                max_diff = diff
            if diff > max(atol, rtol * max(abs(ref), 1.0)) and bad < 0:
                bad = k
    if bad >= 0:
        return {"valid": False,
                "reason": (f"output[{bad}] differs by {max_diff:.3e} "
                           f"(atol={atol:.1e} rtol={rtol:.1e})")}
    return {"valid": True,
            "reason": f"all {N} cells within tolerance (max diff = {max_diff:.3e})"}

