// original_run_length_encoding — RLE compress an int32 sequence.
//
// A "run" is a maximal block of equal consecutive values. Output:
//   P              -- number of runs
//   values[P]      -- the value of each run (in order)
//   counts[P]      -- the run length of each run
//
// Output is uniquely determined for any correct implementation.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 x[N]]
//   argv[2] = output.bin  [int32 P][int32 values[P]][int32 counts[P]]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    std::vector<int32_t> x(N);
    if (std::fread(x.data(), sizeof(int32_t), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    std::vector<int32_t> values, counts;
    int i = 0;
    while (i < N) {
        int32_t v = x[i];
        int32_t c = 1;
        while (i + c < N && x[i + c] == v) ++c;
        values.push_back(v);
        counts.push_back(c);
        i += c;
    }
    int32_t P = (int32_t)values.size();

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(&P,            sizeof(int32_t), 1, fout);
    std::fwrite(values.data(), sizeof(int32_t), P, fout);
    std::fwrite(counts.data(), sizeof(int32_t), P, fout);
    std::fclose(fout);
    return 0;
}

// original_inversion_count — count pairs (i, j) with i < j and a[i] > a[j].
//
// Output is a uniquely determined int64 (count fits in int64 for any
// reasonable N up to a few hundred million).
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 a[N]]
//   argv[2] = output.bin  [int64 count]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    std::vector<int32_t> a(N);
    if (std::fread(a.data(), sizeof(int32_t), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    int64_t count = 0;
    for (int i = 0; i < N; ++i)
        for (int j = i + 1; j < N; ++j)
            if (a[i] > a[j]) ++count;

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(&count, sizeof(int64_t), 1, fout);
    std::fclose(fout);
    return 0;
}

// original_sieve_of_eratosthenes — find all primes up to N (inclusive).
//
// Output is a bitmap: is_prime[k] = 1 if k is prime, else 0.
// is_prime[0] = is_prime[1] = 0.
//
// Output is uniquely determined; bytes match for any correct impl.
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N]   (N >= 2)
//   argv[2] = output.bin  [uint8 is_prime[N+1]]

#include <cstdint>
#include <cstdio>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N < 2) { std::fclose(fin); return 1; }
    std::fclose(fin);

    std::vector<uint8_t> is_prime((std::size_t)N + 1, 1);
    is_prime[0] = is_prime[1] = 0;
    for (int p = 2; (int64_t)p * p <= N; ++p) {
        if (is_prime[p]) {
            for (int64_t q = (int64_t)p * p; q <= N; q += p) {
                is_prime[(std::size_t)q] = 0;
            }
        }
    }

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(is_prime.data(), 1, is_prime.size(), fout);
    std::fclose(fout);
    return 0;
}

// original_top_k_indices — return any K indices that select the K
// largest values. Output the indices in ASCENDING order to canonicalize
// trivial reorderings; ties at the K-th boundary value still allow
// multiple valid answers (different equally-valued indices may be
// chosen).
//
// Binary I/O contract:
//   argv[1] = input.bin   [int32 N][int32 K][double values[N]]
//   argv[2] = output.bin  [int32 indices[K]]      sorted ascending

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <numeric>
#include <vector>

int main(int argc, char* argv[]) {
    if (argc != 3) return 1;
    FILE* fin = std::fopen(argv[1], "rb");
    if (!fin) return 1;
    int32_t N = 0, K = 0;
    if (std::fread(&N, sizeof(int32_t), 1, fin) != 1 || N <= 0) { std::fclose(fin); return 1; }
    if (std::fread(&K, sizeof(int32_t), 1, fin) != 1 || K < 0 || K > N) { std::fclose(fin); return 1; }
    std::vector<double> v(N);
    if (std::fread(v.data(), sizeof(double), N, fin) != (std::size_t)N) { std::fclose(fin); return 1; }
    std::fclose(fin);

    std::vector<int32_t> idx(N);
    std::iota(idx.begin(), idx.end(), 0);
    // Partial-sort top K by value descending; tie-break by lower index
    std::partial_sort(idx.begin(), idx.begin() + K, idx.end(),
                      [&](int a, int b) {
                          if (v[a] != v[b]) return v[a] > v[b];
                          return a < b;
                      });
    idx.resize(K);
    std::sort(idx.begin(), idx.end());   // canonicalize: ascending

    FILE* fout = std::fopen(argv[2], "wb");
    if (!fout) return 1;
    std::fwrite(idx.data(), sizeof(int32_t), K, fout);
    std::fclose(fout);
    return 0;
}

