"""Checker for top_k_indices (P030).

Validity criteria:
  1. K distinct indices in [0, N), output sorted ascending.
  2. The multiset of values at those K indices equals the K largest
     values of the input. This naturally allows any tie-break choice
     among equally-valued candidates at the K-th boundary.
"""
import struct
from collections import Counter


def check(input_bytes: bytes, output_bytes: bytes) -> dict:
    if len(input_bytes) < 8:
        return {"valid": False, "reason": "input too short"}
    N = struct.unpack("<i", input_bytes[:4])[0]
    K = struct.unpack("<i", input_bytes[4:8])[0]
    if N <= 0 or K < 0 or K > N:
        return {"valid": False, "reason": f"invalid N={N} or K={K}"}
    expected_in = 8 + 8 * N
    if len(input_bytes) != expected_in:
        return {"valid": False,
                "reason": f"input size {len(input_bytes)}, expected {expected_in}"}
    v = struct.unpack(f"<{N}d", input_bytes[8:expected_in])

    if len(output_bytes) != 4 * K:
        return {"valid": False,
                "reason": f"output size {len(output_bytes)}, expected {4*K}"}
    idx = struct.unpack(f"<{K}i", output_bytes)

    # 1. distinct, in range, sorted ascending
    if len(set(idx)) != K:
        return {"valid": False, "reason": "duplicate index in output"}
    for i in idx:
        if not (0 <= i < N):
            return {"valid": False, "reason": f"index {i} out of [0, {N})"}
    for j in range(1, K):
        if idx[j] <= idx[j-1]:
            return {"valid": False,
                    "reason": f"output not sorted ascending at j={j}"}

    # 2. multiset of selected values matches top-K values of input
    sel_vals = sorted([v[i] for i in idx], reverse=True)
    ref_topK = sorted(v, reverse=True)[:K]
    if sel_vals != ref_topK:
        return {"valid": False,
                "reason": (f"selected values do not match top-K "
                           f"(top selected: {sel_vals[:3]}..., "
                           f"top expected: {ref_topK[:3]}...)")}
    return {"valid": True,
            "reason": f"all {K} indices select valid top-K values"}
